mechanics.registerExample:
// ThemeRuntime.register(definition) -> disposer
// definition shape (types client/index.d.ts): { id: string, colorScheme: 'light' | 'dark', tokens: Record<string, string> }
ctx.effect(() => ctx.theme.register({
  id: "h4x0r-neon",
  colorScheme: "dark",
  tokens: {
    "--dsw-alias-bg-base": "var(--dsw-static-neutral-bluish-950)",
    "--dsw-alias-label-primary": "var(--dsw-static-neutral-bluish-50)"
  }
}), "h4x0r: theme registration")
// token-level analogue (pairs, required for every token):
ctx.effect(() => ctx.theme.overrideTokens("h4x0r-neon", {
  "--dsw-alias-bg-base": { light: "#f5f6f7", dark: "#0f1115" }
}), "h4x0r: token layer")

