// registered by ui-theme itself, ui-theme/lib/client.js:2046-2053
ctx.slots.inject("settings.general.item", () => ctx.slots.register({
  name: "settings.general.item",
  id: "h4x0r-theme-picker",
  order: 12,                       // Appearance is 10, font settings is 11
  store,                           // defineStore handle, read through props.useStore
  locale: SETTINGS_NS,             // locale namespace for props.t
  inject: (actions) => {           // store actions are handed in here
    bound = actions
    sync(theme.getTheme())
    return {
      setTheme: (id) => { theme.setTheme(id) }
    }
  }
}, ThemePickerRow), "h4x0r: theme picker row")
// the row store mirrors the service snapshot (ui-theme/lib/client.js:1369-1381)
defineStore({
  init: () => ({ preference: "system", revision: -1 }),
  actions: { sync: (d, preference, revision) => {
    if (revision <= d.revision) return
    d.preference = preference
    d.revision = revision
  } }
})
// the plugin's only writer is its own theme/change listener (ui-theme/lib/client.js:2034-2045)
ctx.on("theme/change", sync)
